'use strict';

import { createError, IDB_ERROR } from 'pouchdb-errors';
import { collectConflicts } from 'pouchdb-merge';

import { DOC_STORE, processAttachment } from './util';

const LOCAL_PREFIX = '_local';

function allDocsKeys(keys, docStore, allDocsInner) {
  // It's not guaranted to be returned in right order
  const valuesBatch = new Array(keys.length);
  let count = 0;
  keys.forEach(function (key, index) {
    docStore.get(key).onsuccess = function (event) {
      valuesBatch[index] = event.target.result || {key, error: 'not_found'};
      if (++count === keys.length) valuesBatch.forEach(allDocsInner);
    };
  });
}

function createKeyRange(start, end, inclusiveEnd, key, descending) {
  try {
    if (start && end) {
      if (descending) {
        return IDBKeyRange.bound(end, start, !inclusiveEnd, false);
      } else {
        return IDBKeyRange.bound(start, end, false, !inclusiveEnd);
      }
    } else if (start) {
      if (descending) {
        return IDBKeyRange.upperBound(start);
      } else {
        return IDBKeyRange.lowerBound(start);
      }
    } else if (end) {
      if (descending) {
        return IDBKeyRange.lowerBound(end, !inclusiveEnd);
      } else {
        return IDBKeyRange.upperBound(end, !inclusiveEnd);
      }
    } else if (key) {
      return IDBKeyRange.only(key);
    }
  } catch (e) {
    return {error: e};
  }
  return null;
}

function handleKeyRangeError(opts, metadata, err, callback) {
  if (err.name === "DataError" && err.code === 0) {
    // data error, start is less than end
    var returnVal = {
      total_rows: metadata.doc_count,
      offset: opts.skip,
      rows: []
    };
    /* istanbul ignore if */
    if (opts.update_seq) {
      returnVal.update_seq = metadata.seq;
    }
    return callback(null, returnVal);
  }
  callback(createError(IDB_ERROR, err.name, err.message));
}

export default function (txn, metadata, opts, callback) {
  if (txn.error) {
    return callback(txn.error);
  }

  // TODO: Weird hack, I dont like it
  if (opts.limit === 0) {
    var returnVal = {
      total_rows: metadata.doc_count,
      offset: opts.skip,
      rows: []
    };

    /* istanbul ignore if */
    if (opts.update_seq) {
      returnVal.update_seq = metadata.seq;
    }
    txn.txn.commit();
    return callback(null, returnVal);
  }

  var results = [];
  var processing = [];

  var start = 'startkey' in opts ? opts.startkey : false;
  var end = 'endkey' in opts ? opts.endkey : false;
  var key = 'key' in opts ? opts.key : false; // TODO how does this interact with skip & limit?  Surely a specific key with skip > 0 => no result?
  var keys = 'keys' in opts ? opts.keys : false;
  var skip = opts.skip || 0;
  var limit = typeof opts.limit === 'number' ? opts.limit : -1;
  var inclusiveEnd = opts.inclusive_end !== false;
  var descending = 'descending' in opts && opts.descending ? 'prev' : null;

  var keyRange;
  if (!keys) {
    keyRange = createKeyRange(start, end, inclusiveEnd, key, descending);
    if (keyRange && keyRange.error) {
      return handleKeyRangeError(opts, metadata, keyRange.error, callback);
    }
  }

  var docStore = txn.txn.objectStore(DOC_STORE);

  let allDocsInner;

  txn.txn.oncomplete = onTxnComplete;

  if (keys) {
    allDocsInner = doc => {
      if (doc.error) {
        // key was not found with "keys" requests
        results.push(doc);
        return true;
      }

      const row = {
        id: doc.id,
        key: doc.id,
        value: {
          rev: doc.rev
        }
      };

      if (doc.deleted) {
        results.push(row);
        row.value.deleted = true;
        row.doc = null;
      } else if (--skip < 0) {
        results.push(row);
        if (opts.include_docs) {
          include_doc(processing, opts, row, doc);
        }
        if (--limit === 0) {
          return false;
        }
      }
      return true;
    };
    return allDocsKeys(keys, docStore, allDocsInner);
  } else {
    allDocsInner = doc => {
      if (doc.deleted) {
  // skip
      } else if (--skip < 0) {
        const row = { id:doc.id, key:doc.id, value:{ rev:doc.rev } };
        results.push(row);
        if (opts.include_docs) {
          include_doc(processing, opts, row, doc);
        }
        if (--limit === 0) {
          return false;
        }
      }
      return true;
    };
  }

  function onTxnComplete() {
    Promise.all(processing).then(function () {
      var returnVal = {
        total_rows: metadata.doc_count,
        offset: 0,
        rows: results
      };

      /* istanbul ignore if */
      if (opts.update_seq) {
        returnVal.update_seq = metadata.seq;
      }
      callback(null, returnVal);
    });
  }

  if(descending) { // TODO this can use the new code too, but we'll have to adapt createKeyRange()... carefully!
    var cursor = descending ?
      docStore.openCursor(keyRange, descending) :
      docStore.openCursor(keyRange);

    cursor.onsuccess = function (e) {
      const cursor = e.target.result;

      // Happens if opts does not have limit,
      // because cursor will end normally then,
      // when all docs are retrieved.
      // Would not be needed, if getAll() optimization was used like in #6059
      if(!cursor) return txn.txn.commit();

      const id = cursor.key;

      if(id.startsWith(LOCAL_PREFIX)) return cursor.continue();

      const doc = cursor.value;

      const carryOn = allDocsInner(doc);

      if(carryOn) {
        cursor.continue();
      } else {
        // TODO added .commit() cuz maybe committing here is an optimisation?
        txn.txn.commit();
      }
    };
  } else {
    newFetch(processing, results, txn, docStore, opts, keyRange, inclusiveEnd, skip, limit);
  }
}

function newFetch(processing, results, txn, docStore, opts, keyRange, inclusiveEnd, skip, limit) {
  if(limit === -1) limit = undefined;

  const latestRevsIndex = docStore.index('___latest_revs');

  if(skip) {
    // TODO we may want to batch this getAllKeys() request, as it may load many many keys.
    // However, if each key is [ integer, id-string, rev-string ] then maybe of the order
    // of 100 bytes, so loading 1,000,000 keys would be 100 MB.  Is this a lot of docs to
    // have in a db?  Is 100 MB of data in RAM acceptable?
    latestRevsIndex.getAllKeys(keyRange).onsuccess = (e) => {
      const keys = e.target.result;

      const lastSkipped = keys[skip-1];
      if(lastSkipped === undefined) {
        // no results
        return txn.txn.commit();
      }

      if(!keyRange || !keyRange.upper) {
        // this means this is the first batch, and createKeyRange() returned null
        keyRange = IDBKeyRange.lowerBound(lastSkipped.id, true);
      } else {
        keyRange = IDBKeyRange.bound(lastSkipped.id, keyRange.upper, true, !inclusiveEnd);
      }

      fetchResults();
    };
  } else {
    fetchResults();
  }

  function fetchResults() {
    if(opts.include_docs) {
      latestRevsIndex.getAll(keyRange, limit).onsuccess = (e) => {
        const values = e.target.result;
        for(let i=0; i<values.length; ++i) {
          const doc = values[i];
          const row = { id:doc.id, key:doc.id, value:{ rev:doc.rev } };
          include_doc(processing, opts, row, doc);
          results[i] = row;
        }
        return txn.txn.commit();
      };
    } else {
      // we can now create the result skelingtons from the getAllKeys() result
      latestRevsIndex.getAllKeys(keyRange, limit).onsuccess = (e) => {
        const values = e.target.result;
        for(let i=0; i<values.length; ++i) {
          const doc = values[i];
          results[i] = { id:doc.id, key:doc.id, value:{ rev:doc.rev } };
        }
        return txn.txn.commit();
      };
    }
  }

  function handleOnSuccess() {
  }
}

function include_doc(processing, opts, row, doc) {
  var docData = doc.revs[doc.rev].data;

  row.doc = docData;
  row.doc._id = doc.id;
  row.doc._rev = doc.rev;
  if (opts.conflicts) {
    var conflicts = collectConflicts(doc);
    if (conflicts.length) {
      row.doc._conflicts = conflicts;
    }
  }
  if (opts.attachments && docData._attachments) {
    for (var name in docData._attachments) {
      processing.push(processAttachment(name, doc, row.doc, opts.binary));
    }
  }
}
